static const SPAsset sp_slime_asset = {"Corrected jelly study","f660b1f4b14f4105b21151358a0b468c39f03207b20c691a30facb0a486ccb4a",7483,44862,3,2,10,sp_jelly_p,sp_jelly_n,sp_jelly_uv,sp_jelly_indices,sp_jelly_submeshes,sp_jelly_materials,sp_jelly_clips};
/* Node scale must follow the local eye morph, then the root affine scale.
 * Combining the scales with the blink morph buries the fitted rims. Normals
 * use the inverse transpose, including the independently scaled eye nodes. */
static float sp_jelly_sqrt(float x){float r=x>1?x:1;for(unsigned i=0;i<16;i++)r=(r+x/r)*.5f;return r;}
static int sp_decode_frame(const SPAsset *asset,unsigned clip,unsigned frame,SPVec3 *p,SPVec3 *n){
 if(asset!=&sp_slime_asset||clip>=asset->clip_count||!p||!n)return 0;
 const SPClip *c=asset->clips+clip;if(frame>=c->frame_count)return 0;
 const float *a=c->channels+frame*27;
 for(unsigned part=0;part<3;part++){
  const SPJellyPart *s=sp_jelly_parts+part;const float *w=a+part*7;
  for(unsigned j=0;j<s->count;j++){
   unsigned v=s->offset+j;SPVec3 pos=asset->positions[v],normal=asset->normals[v];
   for(unsigned k=0;k<4;k++){
    SPVec3 d=s->dp[k*s->count+j],dn=s->dn[k*s->count+j];
    pos.x+=w[k]*d.x;pos.y+=w[k]*d.y;pos.z+=w[k]*d.z;
    normal.x+=w[k]*dn.x;normal.y+=w[k]*dn.y;normal.z+=w[k]*dn.z;
   }
   float sx=w[4]*a[24],sy=w[5]*a[25],sz=w[6]*a[26];
   p[v]=(SPVec3){pos.x*sx+a[21],pos.y*sy+a[22],pos.z*sz+a[23]};
   normal.x/=sx;normal.y/=sy;normal.z/=sz;
   float length=sp_jelly_sqrt(normal.x*normal.x+normal.y*normal.y+normal.z*normal.z);
   n[v]=(SPVec3){normal.x/length,normal.y/length,normal.z/length};
  }
 }
 return 1;
}
